1	import { finding } from '../../../../engine/checks/helpers/findings.mjs';
2	
3	// Converted from this pack's prose: the nightly baselining that lands a
4	// `seededByDefault` pack on every member is gated `!isHome`, so the canon home is
5	// the one repo it never reaches — a newly seeded pack arrives everywhere except
6	// here, silently, and the home runs a fleet-wide pack short until someone
7	// notices. The invariant that closes it is a static one: every non-local pack
8	// whose module flags `seededByDefault` is named in the home's own
9	// `.claudinite-checks.json`. Two files, one comparison — so it converts.
10	//
11	// PARSED, NOT GREPPED (the skill's rule): `git grep seededByDefault` also hits
12	// the prose *about* seeding and the engine code that reads the flag. This scans
13	// exactly the pack modules the home's own `packs/` tree carries, with their
14	// comments blanked out first, so a pack.mjs that merely discusses the flag in a
15	// comment is not mistaken for one that sets it.
16	//
17	// Scope is the home's OWN packs/ tree (`packs/<name>/pack.mjs`): a consumer's
18	// canon lives under `.claudinite/shared/packs/`, which this rule never reads —
19	// and the rule runs only where this local pack is declared, which is the home.
20	// Local packs are excluded by construction (they are hand-declared, never
21	// seeded), and the rule self-skips in any repo with no `packs/` tree.
22	
23	const PACK_MODULE = /^packs\/([^/]+)\/pack\.mjs$/;
24	const SETTINGS = '.claudinite-checks.json';
25	const SEEDED = /(^|[^\w.$])seededByDefault\s*:\s*true\b/;
26	const ID = /(^|[^\w.$])id\s*:\s*(['"`])([^'"`]+)\2/;
27	
28	// `source` with its comments blanked out (newlines kept, so nothing shifts).
29	// Walks strings and template literals so a `//` inside one is left alone.
30	function stripComments(source) {
31	  let out = '';
32	  let i = 0;
33	  while (i < source.length) {
34	    const c = source[i];
35	    if (c === '"' || c === "'" || c === '`') {
36	      const quote = c;
37	      out += c;
38	      i += 1;
39	      while (i < source.length && source[i] !== quote) {
40	        if (source[i] === '\\') { out += source.slice(i, i + 2); i += 2; continue; }
41	        out += source[i];
42	        i += 1;
43	      }
44	      out += source[i] ?? '';
45	      i += 1;
46	      continue;
47	    }
48	    if (c === '/' && source[i + 1] === '/') {
49	      while (i < source.length && source[i] !== '\n') { out += ' '; i += 1; }
50	      continue;
51	    }
52	    if (c === '/' && source[i + 1] === '*') {
53	      const end = source.indexOf('*/', i + 2);
54	      const stop = end === -1 ? source.length : end + 2;
55	      out += source.slice(i, stop).replace(/[^\n]/g, ' ');
56	      i = stop;
57	      continue;
58	    }
59	    out += c;
60	    i += 1;
61	  }
62	  return out;
63	}
64	
65	const rule = {
66	  id: 'home-seeded-packs-declared',
67	  severity: 'blocking',
68	  description: "The canon home's .claudinite-checks.json declares every non-local pack that flags seededByDefault",
69	  doc: '.claudinite/local/packs/claudinite/RULES.md',
70	  why: 'the baselining that lands a seeded pack on every member is gated !isHome, so a newly seeded pack reaches the whole fleet except this repo — and the gap is invisible until something the pack was supposed to enforce goes missing here',
71	
72	  run(ctx) {
73	    const modules = ctx.tracked.filter((f) => PACK_MODULE.test(f));
74	    // Not the canon home (a consumer's canon lives under the shared mount, and a
75	    // repo with no settings file has no declaration to judge) — nothing to say.
76	    if (modules.length === 0 || ctx.read(SETTINGS) === null) return [];
77	
78	    const declared = new Set(ctx.config?.packs ?? []);
79	    const out = [];
80	    for (const file of modules.sort()) {
81	      const source = ctx.read(file);
82	      if (source === null) continue;
83	      const code = stripComments(source);
84	      if (!SEEDED.test(code)) continue;
85	      const id = ID.exec(code)?.[3] ?? PACK_MODULE.exec(file)[1];
86	      if (declared.has(id)) continue;
87	      out.push(finding(rule, {
88	        file: SETTINGS,
89	        line: null,
90	        what: `the "${id}" pack flags seededByDefault (${file}) but is not declared here`,
91	        fix: `add "${id}" to the "packs" array in ${SETTINGS} — the fleet's baselining skips this repo, so the home's declaration is hand-maintained; if the home is deliberately opting out, record an acceptance with the reason instead`,
92	      }));
93	    }
94	    return out;
95	  },
96	};
97	
98	export default rule;
